import Foundation
import CRMCore

func runInboxTargetAssignmentChecks(directory:URL) async throws -> Int {
    var count=0
    func expect(_ value:Bool,_ message:String) throws {guard value else {throw CheckFailure(message:message)};count += 1}
    let d=try JSONSerialization.jsonObject(with:Data(contentsOf:directory.appendingPathComponent("inbox-target-assignment.json"))) as! [String:Any],members=APITeamMemberReadRepository(transport:FixtureTeamMemberReadTransport(directory:directory)),fixture=FixtureInboxTargetAssignmentPort(directory:directory)
    func context(_ x:[String:Int])->InboxConversationFilesContext {InboxConversationFilesContext(business:x["business"]!,conversation:x["conversation"]!,epoch:x["epoch"]!,revision:x["revision"]!)}
    func reference(_ c:InboxConversationFilesContext,id:Int=8101) async throws -> QualifiedMemberReference? {var s=MemberReferenceSession();s.bind(c);s.show();s.update("00"+String(id),input:s.input);let t=s.begin(expected:s.control)!;s.accept(try await members.member(business:c.business,id:id),ticket:t);s.use(expected:s.control);return s.choice}
    let c=context(d["context"] as! [String:Int]),source=InboxTargetAssignmentSource.decode(Data((d["source_json"] as! String).utf8),context:c)!,ref=try await reference(c)!,auth=fixture.grants[0].authorization(for:c)!,target=fixture.targetMemberships.first {$0.matches(ref)}!,candidate=InboxTargetAssignmentCandidate(source:source,reference:ref)!,review=InboxTargetAssignmentReview(source:source,authorization:auth,candidate:candidate,targetMembership:target,visit:1)
    for x in d["source_cases"] as! [[String:Any]] {try expect((InboxTargetAssignmentSource.decode(Data((x["response_json"] as! String).utf8),context:context(x["context"] as! [String:Int])) != nil)==x["valid"] as! Bool,"Exact assigned_to source \(x["name"]!)")}
    for x in d["grant_cases"] as! [[String:Any]] {let g=try JSONDecoder().decode(SyntheticInboxTargetAssignmentGrant.self,from:JSONSerialization.data(withJSONObject:x["grant"]!));try expect((g.authorization(for:c) != nil)==x["valid"] as! Bool,"Independent MANAGE \(x["name"]!)")}
    for x in d["target_cases"] as! [[String:Any]] {let t=try JSONDecoder().decode(SyntheticInboxTargetMembershipContext.self,from:JSONSerialization.data(withJSONObject:x["target"]!));try expect(t.matches(ref)==x["valid"] as! Bool,"Separate target membership \(x["name"]!)");try expect(InboxTargetAssignmentReview(source:source,authorization:auth,candidate:candidate,targetMembership:t,visit:1).valid==x["valid"] as! Bool,"Review lost target context")}
    try expect(ref.source.id==8101 && ref.source.user.id==5002 && ref.rawInput=="008101" && review.valid,"Membership record confused with User or raw input lost")
    let inactive=try await reference(c,id:8102);try expect(inactive==nil,"Observed inactive membership qualified")
    let accountInactive=try await reference(c,id:8103);try expect(accountInactive?.source.user.id==5004,"Account field replaced Business membership observation")
    for next in [InboxConversationFilesContext(business:101,conversation:902,epoch:700,revision:1),InboxConversationFilesContext(business:101,conversation:901,epoch:701,revision:1),InboxConversationFilesContext(business:101,conversation:901,epoch:700,revision:2),InboxConversationFilesContext(business:202,conversation:951,epoch:700,revision:1)] {let q=try await reference(next,id:next.business==101 ? 8101:9101)!;try expect(InboxTargetAssignmentCandidate(source:source,reference:q)==nil,"Foreign/stale owner accepted")}
    var ledger=InboxTargetAssignmentLedger();let a=ledger.begin(review)!,body=try JSONSerialization.jsonObject(with:a.preparedBody()) as! [String:Int]
    try expect(body==["user_id":5002] && a.path=="/api/inbox/conversations/901/assign/" && a.query.isEmpty && a.headers.isEmpty,"Selected-user body used Member id/null/self/default/extra data")
    try expect(ledger.begin(review)==nil && !ledger.acknowledge(auth,record:ledger.visible(auth)!),"Pending duplicated or acknowledged")
    for x in d["receipt_cases"] as! [[String:Any]] {try expect((InboxTargetAssignmentReceipt.decode(Data((x["response_json"] as! String).utf8),attempt:a) != nil)==x["valid"] as! Bool,"Exact selected User receipt \(x["name"]!)")}
    ledger.complete(a,outcome:try await fixture.execute(a));let known=ledger.visible(auth)!;try expect(known.phase == .response && known.result?.source.assignedTo==5002 && known.attempt.review.source.assignedTo==7000,"Synthetic response patched original");ledger.complete(a,outcome:.unknown);try expect(ledger.visible(auth)==known && ledger.acknowledge(auth,record:known),"Late duplicate replaced known/history")
    let unknownAttempt=ledger.begin(review)!;ledger.complete(unknownAttempt,outcome:.unknown);let unknown=ledger.visible(auth)!
    let next=InboxConversationFilesContext(business:101,conversation:901,epoch:702,revision:2),nextRef=try await reference(next,id:8103)!,nextSource=InboxTargetAssignmentSource.decode(try JSONSerialization.data(withJSONObject:["id":901,"business":101,"assigned_to":5002,"updated_at":"matching reread"]),context:next)!,nextAuth=fixture.grants[0].authorization(for:next)!,nextReview=InboxTargetAssignmentReview(source:nextSource,authorization:nextAuth,candidate:InboxTargetAssignmentCandidate(source:nextSource,reference:nextRef)!,targetMembership:fixture.targetMemberships.first {$0.matches(nextRef)}!,visit:2)
    try expect(ledger.visible(nextAuth)==unknown && ledger.begin(nextReview)==nil && !ledger.acknowledge(nextAuth,record:unknown) && unknown.attempt==unknownAttempt && unknown.attempt.review.candidate.reference==ref,"Matching GET/member reread/new target/epoch recovered unknown")
    let other=SyntheticInboxTargetAssignmentGrant(business:101,conversation:901,actor:6001,manage:true).authorization(for:next)!;try expect(ledger.visible(other)==nil && ledger.blocked(business:101,conversation:901) && !ledger.blocked(business:202,conversation:951),"Actor/scope barrier lost")
    for status in [201,202,204,400,403,409,500] {var l=InboxTargetAssignmentLedger();let attempt=l.begin(review)!;l.complete(attempt,outcome:.response(status:status,data:try JSONSerialization.data(withJSONObject:["id":901,"business":101,"assigned_to":5002,"updated_at":"test"])));try expect(l.visible(auth)?.phase == .unknown,"Non-plain200 inferred known result")}
    var rejection=InboxTargetAssignmentLedger();let rejected=rejection.begin(review)!;rejection.complete(rejected,outcome:.rejectedWithoutWrite);let record=rejection.visible(auth)!;try expect(record.phase == .rejected && rejection.acknowledge(auth,record:record) && rejection.records.count==1,"Definite fake rejection/history lost")
    return count
}
